-- 0019 — Catálogo de presentes ampliado: 105 cotas em 10 categorias (era 51 em 7).
-- Seguro para re-executar: reescreve cada item pelo id (não mexe em `active`).
--
-- Novas categorias: Eletrodomésticos, Eletroportáteis, Cama, mesa e banho e
-- Casa e decoração (que substitui "Casa nova"). Itens antigos mudaram de categoria
-- e de ordem; os que ganharam foto de produto mais clara ou foto engraçada (Cotas
-- divertidas) usam um arquivo novo (*-2.webp). O arquivo antigo continua no ar,
-- porque as cotas que os casais já adicionaram guardam o caminho da foto.
--
-- Fotos: Pexels (licença Pexels: uso comercial livre, sem atribuição obrigatória),
-- servidas pelo próprio Noivar em /assets/presentes. image_source = página de origem.
-- Aplique no SQL Editor do Supabase junto com o deploy que traz as fotos novas.

on conflict (id) do update set
  category     = excluded.category,
  title        = excluded.title,
  description  = excluded.description,
  price        = excluded.price,
  image        = excluded.image,
  image_source = excluded.image_source,
  sort         = excluded.sort;
